1	import React from 'react';
2	
3	export interface InputProps extends React.InputHTMLAttributes<HTMLInputElement> {
4	  label?: string;
5	  placeholder?: string;
6	  value?: string;
7	  onChange?: (e: React.ChangeEvent<HTMLInputElement>) => void;
8	  error?: string;
9	  helper?: string;
10	  icon?: React.ReactNode;
11	  type?: string;
12	  className?: string;
13	}
14	
15	export function Input({
16	  label,
17	  placeholder,
18	  value,
19	  onChange,
20	  error,
21	  helper,
22	  icon,
23	  type = 'text',
24	  className = '',
25	  id,
26	  ...props
27	}: InputProps) {
28	  const inputId = id || (label ? label.toLowerCase().replace(/\s+/g, '-') : undefined);
29	  const errorId = inputId ? `${inputId}-error` : undefined;
30	  const helperId = inputId ? `${inputId}-helper` : undefined;
31	  const describedBy = error ? errorId : helper ? helperId : undefined;
32	
33	  return (
34	    <div className={`flex flex-col gap-1.5 ${className}`}>
35	      {label && (
36	        <label htmlFor={inputId} className="input-label">
37	          {label}
38	        </label>
39	      )}
40	      <div className="relative">
41	        {icon && (
42	          <span className="absolute left-3.5 top-1/2 -translate-y-1/2 text-[var(--color-text-muted)] flex pointer-events-none">
43	            {icon}
44	          </span>
45	        )}
46	        <input
47	          id={inputId}
48	          type={type}
49	          placeholder={placeholder}
50	          value={value}
51	          onChange={onChange}
52	          aria-invalid={!!error || undefined}
53	          aria-describedby={describedBy}
54	          className={`input-field ${error ? 'border-[var(--color-error)]! focus:shadow-none!' : ''} ${icon ? 'pl-[42px]' : ''}`}
55	          {...props}
56	        />
57	      </div>
58	      {error && (
59	        <span id={errorId} className="input-error" role="alert">
60	          {error}
61	        </span>
62	      )}
63	      {helper && !error && (
64	        <span id={helperId} className="input-helper">
65	          {helper}
66	        </span>
67	      )}
68	    </div>
69	  );
70	}
71	
72	export default Input;
