3	import React, { createContext, useContext, useState, useCallback, useRef, useEffect } from 'react';
4	import { CheckCircle, XCircle, AlertTriangle, Info, X } from 'lucide-react';
5	
6	type ToastType = 'success' | 'error' | 'warning' | 'info';
7	
8	interface ToastItem {
9	  id: number;
10	  type: ToastType;
11	  message: string;
12	}
13	
14	interface ToastContextValue {
15	  showToast: (type: ToastType, message: string) => void;
16	}
17	
18	const ToastContext = createContext<ToastContextValue | null>(null);
19	
20	const ICONS: Record<ToastType, React.ReactNode> = {
21	  success: <CheckCircle size={18} />,
22	  error: <XCircle size={18} />,
23	  warning: <AlertTriangle size={18} />,
24	  info: <Info size={18} />,
25	};
26	
27	let toastCounter = 0;
28	
29	export function ToastProvider({ children }: { children: React.ReactNode }) {
30	  const [toasts, setToasts] = useState<ToastItem[]>([]);
31	  const timersRef = useRef<Map<number, ReturnType<typeof setTimeout>>>(new Map());
32	
33	  const removeToast = useCallback((id: number) => {
34	    const timer = timersRef.current.get(id);
35	    if (timer) {
36	      clearTimeout(timer);
37	      timersRef.current.delete(id);
38	    }
39	    setToasts((prev) => prev.filter((t) => t.id !== id));
40	  }, []);
41	
42	  const showToast = useCallback(
43	    (type: ToastType, message: string) => {
44	      const id = ++toastCounter;
45	      setToasts((prev) => [...prev, { id, type, message }]);
46	      const timer = setTimeout(() => removeToast(id), 3000);
47	      timersRef.current.set(id, timer);
48	    },
49	    [removeToast]
50	  );
51	
52	  useEffect(() => {
53	    const timers = timersRef.current;
54	    return () => {
55	      timers.forEach((t) => clearTimeout(t));
56	    };
57	  }, []);
58	
59	  return (
60	    <ToastContext.Provider value={{ showToast }}>
61	      {children}
62	      <div className="toast-container" role="status" aria-live="polite">
63	        {toasts.map((toast) => (
64	          <div
65	            key={toast.id}
66	            className={`toast toast-${toast.type}`}
67	            role="alert"
68	          >
69	            {ICONS[toast.type]}
70	            <span style={{ flex: 1 }}>{toast.message}</span>
71	            <button
72	              onClick={() => removeToast(toast.id)}
73	              aria-label="Dismiss notification"
74	              style={{
75	                background: 'none',
76	                border: 'none',
77	                color: 'inherit',
78	                cursor: 'pointer',
79	                padding: 2,
80	                display: 'flex',
81	                opacity: 0.8,
82	              }}
83	            >
84	              <X size={14} />
85	            </button>
86	          </div>
87	        ))}
88	      </div>
89	    </ToastContext.Provider>
90	  );
91	}
92	
93	export function useToast(): ToastContextValue {
94	  const ctx = useContext(ToastContext);
95	  if (!ctx) throw new Error('useToast must be used within a ToastProvider');
96	  return ctx;
97	}
