3	import { useEffect, useState } from 'react';
4	import { Download, X } from 'lucide-react';
5	
6	interface BeforeInstallPromptEvent extends Event {
7	  prompt: () => Promise<void>;
8	  userChoice: Promise<{ outcome: 'accepted' | 'dismissed' }>;
9	}
10	
11	const DISMISS_KEY = 'gccstartup-install-dismissed';
12	const VISIT_KEY = 'gccstartup-visit-count';
13	
14	function getVisitCount(): number {
15	  if (typeof window === 'undefined') return 0;
16	  const count = parseInt(localStorage.getItem(VISIT_KEY) || '0', 10);
17	  return count;
18	}
19	
20	function incrementVisitCount() {
21	  const count = getVisitCount();
22	  localStorage.setItem(VISIT_KEY, String(count + 1));
23	}
24	
25	export default function InstallPrompt() {
26	  const [deferredPrompt, setDeferredPrompt] = useState<BeforeInstallPromptEvent | null>(null);
27	  const [visible, setVisible] = useState(false);
28	
29	  useEffect(() => {
30	    incrementVisitCount();
31	
32	    const dismissed = localStorage.getItem(DISMISS_KEY);
33	    if (dismissed) return;
34	
35	    const visitCount = getVisitCount();
36	    if (visitCount < 2) return;
37	
38	    const handler = (e: Event) => {
39	      e.preventDefault();
40	      setDeferredPrompt(e as BeforeInstallPromptEvent);
41	      setVisible(true);
42	    };
43	
44	    window.addEventListener('beforeinstallprompt', handler);
45	    return () => window.removeEventListener('beforeinstallprompt', handler);
46	  }, []);
47	
48	  const handleInstall = async () => {
49	    if (!deferredPrompt) return;
50	
51	    deferredPrompt.prompt();
52	    const { outcome } = await deferredPrompt.userChoice;
53	
54	    if (outcome === 'accepted') {
55	      setVisible(false);
56	    }
57	    setDeferredPrompt(null);
58	  };
59	
60	  const handleDismiss = () => {
61	    localStorage.setItem(DISMISS_KEY, 'true');
62	    setVisible(false);
63	    setDeferredPrompt(null);
64	  };
65	
66	  if (!visible || !deferredPrompt) return null;
67	
68	  return (
69	    <div className="fixed bottom-4 left-4 right-4 z-50 sm:left-auto sm:right-4 sm:w-96">
70	      <div className="rounded-xl border border-[var(--color-border,#E5E7EB)] bg-white p-4 shadow-lg">
71	        <div className="flex items-start justify-between gap-3">
72	          <div className="flex items-center gap-3">
73	            <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-lg bg-[#14204A]">
74	              <Download className="h-5 w-5 text-white" />
75	            </div>
76	            <div>
77	              <p className="text-sm font-semibold text-[#14204A]">Install GCCStartup</p>
78	              <p className="text-xs text-gray-500">
79	                Add to your home screen for quick access
80	              </p>
81	            </div>
82	          </div>
83	          <button
84	            onClick={handleDismiss}
85	            className="shrink-0 rounded-md p-1 text-gray-400 transition-colors hover:bg-gray-100 hover:text-gray-600"
86	            aria-label="Dismiss install prompt"
87	          >
88	            <X className="h-4 w-4" />
89	          </button>
90	        </div>
91	        <div className="mt-3 flex gap-2">
92	          <button
93	            onClick={handleInstall}
94	            className="flex-1 rounded-lg bg-[#F26522] px-4 py-2 text-sm font-medium text-white transition-colors hover:bg-[#e55a1b]"
95	          >
96	            Install App
97	          </button>
98	          <button
99	            onClick={handleDismiss}
100	            className="rounded-lg border border-gray-200 px-4 py-2 text-sm font-medium text-gray-600 transition-colors hover:bg-gray-50"
101	          >
102	            Not now
103	          </button>
104	        </div>
105	      </div>
106	    </div>
107	  );
108	}
