1	'use client';
2	
3	import React, { useState, useEffect, useRef } from 'react';
4	import Link from 'next/link';
5	import { useRouter } from 'next/navigation';
6	import { ChevronLeft, Bell, X, CheckCheck } from 'lucide-react';
7	import { usePortalStore } from '@/lib/store';
8	
9	const PAGE_TITLES: Record<string, string> = {
10	  '/tools': 'Tools',
11	  '/tools/agents': 'AI Agents',
12	  '/tools/contracts': 'Contracts',
13	  '/tools/valuation': 'Valuation',
14	  '/portal': 'Portal',
15	  '/portal/dashboard': 'Dashboard',
16	  '/portal/documents': 'Documents',
17	  '/portal/orders': 'Orders',
18	  '/portal/invoicing': 'Invoicing',
19	  '/portal/accounting': 'Accounting',
20	  '/portal/compliance': 'Compliance',
21	  '/portal/banking': 'Banking',
22	  '/portal/settings': 'Settings',
23	  '/profile': 'Profile',
24	};
25	
26	function getTitleForPathname(pathname: string): string {
27	  if (PAGE_TITLES[pathname]) return PAGE_TITLES[pathname];
28	  const segments = pathname.split('/').filter(Boolean);
29	  if (segments.length > 1) {
30	    const last = segments[segments.length - 1];
31	    return last.charAt(0).toUpperCase() + last.slice(1).replace(/-/g, ' ');
32	  }
33	  return segments[0]?.charAt(0).toUpperCase() + (segments[0]?.slice(1) || '');
34	}
35	
36	interface TopBarProps {
37	  isHome?: boolean;
38	  pathname?: string;
39	  title?: string;
40	  rightAction?: React.ReactNode;
41	}
42	
43	export default function TopBar({ isHome = false, pathname = '/', title, rightAction }: TopBarProps) {
44	  const router = useRouter();
45	  const { whatsappLogs, markNotificationRead, markAllNotificationsRead } = usePortalStore();
46	  const [isDrawerOpen, setIsDrawerOpen] = useState(false);
47	  const [mounted, setMounted] = useState(false);
48	  const drawerRef = useRef<HTMLDivElement>(null);
49	
50	  useEffect(() => {
51	    setMounted(true);
52	  }, []);
53	
54	  useEffect(() => {
55	    if (!isDrawerOpen) return;
56	
57	    const handleKeyDown = (e: KeyboardEvent) => {
58	      if (e.key === 'Escape') {
59	        setIsDrawerOpen(false);
60	        return;
61	      }
62	
63	      if (e.key === 'Tab' && drawerRef.current) {
64	        const focusable = drawerRef.current.querySelectorAll<HTMLElement>(
65	          'a[href], button:not([disabled]), textarea, input:not([disabled]), select:not([disabled]), [tabindex]:not([tabindex="-1"])'
66	        );
67	        if (focusable.length === 0) return;
68	        const first = focusable[0];
69	        const last = focusable[focusable.length - 1];
70	
71	        if (e.shiftKey) {
72	          if (document.activeElement === first) {
73	            e.preventDefault();
74	            last.focus();
75	          }
76	        } else {
77	          if (document.activeElement === last) {
78	            e.preventDefault();
79	            first.focus();
80	          }
81	        }
82	      }
83	    };
84	
85	    window.addEventListener('keydown', handleKeyDown);
86	    return () => window.removeEventListener('keydown', handleKeyDown);
87	  }, [isDrawerOpen]);
88	
89	  const unreadCount = mounted ? whatsappLogs.filter((n) => n.status !== 'read').length : 0;
90	  const pageTitle = title || getTitleForPathname(pathname);
91	
92	  return (
93	    <>
94	      <header className={isHome ? 'brand-header' : 'app-header'}>
95	        <div className={isHome ? 'brand-header-inner' : 'app-header-inner'}>
96	          {isHome ? (
97	            <>
98	              <div className="header-left">
99	                <Link href="/" className="topbar-brand-link">
100	                  <div className="topbar-brand-logo">G</div>
101	                  <span className="topbar-brand-text">
102	                    GCC<span className="topbar-brand-highlight">Startup</span>
103	                  </span>
104	                </Link>
105	              </div>
106	              <div className="header-right">
107	                <button
108	                  type="button"
109	                  onClick={() => setIsDrawerOpen(true)}
110	                  className="header-icon-btn"
111	                  aria-label="Notifications"
112	                >
113	                  <Bell size={18} />
114	                  {mounted && unreadCount > 0 && (
115	                    <span className="header-badge">{unreadCount > 9 ? '9+' : unreadCount}</span>
116	                  )}
117	                </button>
118	              </div>
119	            </>
120	          ) : (
121	            <>
122	              <div className="header-left">
123	                <button
124	                  type="button"
125	                  onClick={() => router.back()}
126	                  className="header-back-btn"
127	                  aria-label="Go back"
128	                >
129	                  <ChevronLeft size={20} />
130	                </button>
131	              </div>
132	              <div className="header-center">
133	                <span className="header-title">{pageTitle}</span>
134	              </div>
135	              <div className="header-right">
136	                {rightAction}
137	                <button
138	                  type="button"
139	                  onClick={() => setIsDrawerOpen(true)}
140	                  className="header-icon-btn"
141	                  aria-label="Notifications"
142	                >
143	                  <Bell size={18} />
144	                  {mounted && unreadCount > 0 && (
145	                    <span className="header-badge">{unreadCount > 9 ? '9+' : unreadCount}</span>
146	                  )}
147	                </button>
148	              </div>
149	            </>
150	          )}
151	        </div>
152	      </header>
153	
154	      {isDrawerOpen && (
155	        <div
156	          role="dialog"
157	          aria-modal="true"
158	          aria-label="Notification Center"
